const chainsaw: Item = {
  id: "saw-01",
  name: "Chainsaw, 35 cm bar",
  category: "garden",
  safety_class: "C",
  deposit_cents: 6000,
  status: "in",
};
const inducted: Member = { ...member, inductions: ["C"] };

test("a member without the C induction cannot take a class-C tool", () => {
  expect(canBorrow(member, chainsaw).ok).toBe(false);
});

test("the refusal names the tool and says an induction is needed", () => {
  const decision = canBorrow(member, chainsaw);
  if (decision.ok) throw new Error("expected a refusal");
  expect(decision.reason).toContain("Chainsaw");
  expect(decision.reason.toLowerCase()).toContain("induction");
});

test("a member with the C induction can take a class-C tool that is in", () => {
  expect(canBorrow(inducted, chainsaw)).toEqual({ ok: true });
});

test("a member with no inductions can still take a class-B tool", () => {
  expect(canBorrow(member, { ...ladder, safety_class: "B" })).toEqual({ ok: true });
});

test("an inducted member still cannot take a class-C tool that is out or in repair", () => {
  expect(canBorrow(inducted, { ...chainsaw, status: "out" }).ok).toBe(false);
  expect(canBorrow(inducted, { ...chainsaw, status: "repair" }).ok).toBe(false);
});

